"""Original, fixed, reviewed assessment items. No past-paper text or numeric reskins.
Every published item's symbolic/enumeration check must pass before bank compilation.
"""
from pathlib import Path
import json,math,itertools,hashlib
import sympy as sp
from distractors import D
R=Path(__file__).resolve().parents[2];OUT=R/'data/math-exams';bank=[];checks=[]
x=sp.symbols('x', real=True)
def add(kind,ch,topic,level,stem,answer,steps,verification,expected,options=None,marks=2,parts=None,pitfall='',figure=None):
 expr=sp.sympify(verification);target=sp.sympify(expected);delta=sp.simplify(expr-target)
 assert delta==0,(topic,delta)
 q=dict(id=f'ME26-{kind[0].upper()}{sum(q["kind"]==kind for q in bank)+1:03}',kind=kind,primary_chapter=ch,secondary_chapters=[],subchapter_id=None,topic=topic,difficulty=level,difficulty_status='estimated',difficulty_basis='Author estimate from algebraic depth, domain checks and integration of skills; not student score data.',marks=marks,stem=stem,answer=answer,solution_steps=steps,marking_points=parts or [dict(description='使用正确原理并列出必要条件',marks=1),dict(description='完成推理并核对答案',marks=marks-1)],common_error=pitfall or '核对题设范围、端点和运算符号；仅写结论不能替代作答推理。',question_origin='original_generated',source_inspiration=None,verification_status='verified',verification=dict(method='symbolic_identity_or_independent_enumeration',expression=verification,expected=expected,result='pass'),figure=figure)
 if options is not None:
  assert len(options)==4 and len(set(options))==4
  q.update(options=[dict(text=t,reason=('正确：见完整解析。'if i==0 else f'干扰项：与第{i}类常见符号、条件或运算误差对应，代回不满足本题要求。')) for i,t in enumerate(options)],correct_option=0,marking_points=[dict(description='选中唯一正确选项',marks=2)])
 bank.append(q);checks.append(dict(id=q['id'],topic=topic,result='pass',method=q['verification']['method']))
def mc(ch,t,d,stem,options,steps,expr,val,pitfall='',figure=None):add('mcq',ch,t,d,stem,options[0],steps,expr,val,options=options,pitfall=pitfall,figure=figure)
def wr(ch,t,d,marks,stem,answer,steps,expr,val,parts,pitfall=''):add('written',ch,t,d,stem,answer,steps,expr,val,marks=marks,parts=[dict(description=a,marks=b)for a,b in parts],pitfall=pitfall)
