# Short written section: basic and medium, with question-specific score points.
wr(1,'两线交点与夹角','basic',4,r'求直线\(y=2x+1\)与\(y=-x+7\)的交点；再求两线锐夹角的正切。','交点(2,5)，tanθ=3。',['令2x+1=−x+7，3x=6得x=2。','代回任一直线得y=5；代另一式也是5。','夹角正切=|(2−(−1))/(1+2(−1))|=3，取正锐角。'],'Abs((2-(-1))/(1+2*(-1)))','3',[('联立求x并代回y',2),('正确应用夹角式及绝对值',2)])
wr(3,'二次余式重建','basic',4,r'多项式p除以\((x-1)(x+2)\)的余式为\(ax+b\)。已知\(p(1)=4,p(-2)=-5\)，求余式。','3x+1。',['余式次数小于2，故可设ax+b。','代两个根得a+b=4、−2a+b=−5。','相减3a=9，所以a=3,b=1；两值均可回验。'],'(3*x+1).subs(x,-2)','-5',[('设置线性余式并列两条件',2),('解出a、b并回验',2)])
wr(5,'反函数及定义域','basic',4,r'\(f(x)=\sqrt{x-2}\)，定义域\([2,\infty)\)。求反函数及其定义域。','f⁻¹(x)=x²+2，x≥0。',['令y=√(x−2)，y≥0。','交换变量得x=√(y−2)，所以y=x²+2。','反函数输入域来自原值域[0,∞)，不能扩到所有实数。'],'(sqrt(x-2)**2+2)','x',[('正确交换并解出反函数',2),('写出反函数定义域并解释',2)])
wr(6,'分式不等式区间','basic',4,r'解\(\frac{x-2}{x+1}\ge0\)，写出端点是否可取。','(−∞,−1)∪[2,∞)。',['分母要求x≠−1；零点x=2。','在三段取点测试，(−∞,−1)及(2,∞)为正。','2使分子为0应包含；−1使分母为0必须排除。'],'((x-2)/(x+1)).subs(x,2)','0',[('标出两个临界点并排除分母零点',1),('作符号分析',2),('合并区间并正确端点',1)])
wr(8,'扇形两条件联立','basic',4,r'一扇形半径r>0，弧度角θ>0。已知弧长为12，面积为36，求r和θ。','r=6，θ=2弧度。',['由rθ=12和r²θ/2=36。','第二式除第一式得到r/2=3，所以r=6。','θ=12/6=2；回代面积=36。'],'6**2*2/2','36',[('正确写出弧长和面积式',2),('联立并核对单位',2)])
wr(15,'矩阵解线性系统','basic',4,r'用矩阵或消元解\(2u+v=7,\ u-v=2\)，并回代。','u=3，v=1。',['系数矩阵[[2,1],[1,−1]]行列式−3非0。','两式相加3u=9得u=3，再得v=1。','回代2×3+1=7、3−1=2。'],'det(Matrix([[2,1],[1,-1]]))','-3',[('列矩阵/消元并说明可解',1),('求出u、v',2),('代回两式',1)])
wr(17,'向量垂直与长度','medium',4,r'\(\mathbf a=(t,2),\mathbf b=(3,-6)\)。若两向量垂直，求t及a的长度。','t=4，|a|=2√5。',['垂直且b非0，点积3t−12=0。','t=4；a=(4,2)。','长度√(16+4)=2√5，点积回验0。'],'sqrt(4**2+2**2)','2*sqrt(5)',[('以点积0列式求t',2),('计算模并验证垂直',2)])
wr(19,'委员会限制计数','medium',4,r'从5位女生、4位男生中选3人委员会，要求至少2位女生。求不同委员会数。','50。',['按恰2女1男或3女0男分互斥情况。','前者C(5,2)C(4,1)=40，后者C(5,3)=10。','总数50，使用组合而非排列。'],'binomial(5,2)*binomial(4,1)+binomial(5,3)','50',[('互斥分类并列组合数',2),('求和并检查无序计数',2)])
# Correct the displayed result immediately; arithmetic checks above never certify answer prose automatically.
bank[-1]['answer']='50。'
wr(20,'二项前项与范围','medium',4,r'将\((1+x)^{-2}\)展开至\(x^2\)项，并写出展开适用范围。','1−2x+3x²+…，|x|<1。',['二项系数按r=−2取：1、−2、(−2)(−3)/2=3。','得到1−2x+3x²，余项为更高次。','这是无穷级数局部展开，要求|x|<1；不是全域恒等多项式。'],'diff((1+x)**(-2),x,2).subs(x,0)/2','3',[('求出三项',3),('写明收敛范围',1)])
wr(23,'由斜率和过点求曲线','medium',4,r'曲线的斜率\(y\prime=3x^2-2\)，且经过\((1,4)\)。求曲线方程。','y=x³−2x+5。',['先积分y=x³−2x+C。','用点(1,4)：4=1−2+C，所以C=5。','求导核3x²−2，并代点得到4。'],'diff(x**3-2*x+5,x)','3*x**2-2',[('正确积分及任意常数',2),('用过点定常数并核查',2)])
wr(28,'隐式切线与过点检验','medium',4,r'求\(x^2+xy+y^2=7\)在\((2,1)\)的切线，并验证该点在曲线上。','切线5x+4y=14。',['先核4+2+1=7，点在曲线上。','隐微分y′=−(2x+y)/(x+2y)，在(2,1)为−5/4。','点斜式y−1=−5(x−2)/4，整理5x+4y=14。'],'5*2+4*1','14',[('点在曲线及隐微分',2),('求斜率并写切线',2)])
wr(34,'复数根与实系数','medium',4,r'实系数首一二次方程有一根\(2-3i\)，求此方程，说明另一根。','x²−4x+13=0；另一根2+3i。',['实系数使非实根成共轭对。','根和4、根积4+9=13。','由韦达得x²−4x+13，代2−3i可验为0。'],'expand((Symbol("z")-(2-3*I))*(Symbol("z")-(2+3*I)))','Symbol("z")**2-4*Symbol("z")+13',[('说明共轭根',1),('求和积并构造方程',2),('复核',1)])
# Medium 6-mark questions, with independent multi-stage requirements.
wr(2,'二次根的参数与最值','medium',6,r'\(p(x)=x^2-(t+2)x+2t\)。(a)写出两根；(b)求两个相异正根的t范围；(c)在0<t<2时求两根之积的上确界，并说明是否达到。','根2,t；t>0且t≠2；上确界4，不达到。',['分解p=(x−2)(x−t)。','根正且相异等价于t>0,t≠2。','在0<t<2，积2t严格小于4且可任意接近4，故上确界4但无最大值。'],'expand((x-2)*(x-Symbol("t")))','x**2-(Symbol("t")+2)*x+2*Symbol("t")',[('因式分解及两根',2),('完整参数条件',2),('区分上确界和最大值',2)])
wr(5,'复合域与反函数验证','medium',6,r'\(f(x)=\ln(x-1),\ g(x)=x^2+1\)。(a)求f∘g及其定义域；(b)把g限制在x≥0，求g⁻¹；(c)解释为什么不能在全实数域给g唯一反函数。','f(g(x))=ln(x²)，x≠0；g⁻¹(x)=√(x−1)，x≥1；全域g非单射。',['复合真数x²>0，所以原域是R去掉0。','限制非负支后由y=x²+1解出x=√(y−1)，输入y≥1。','全域g(1)=g(−1)=2，反函数不唯一；限制分支不可省。'],'log((x**2+1)-1)','log(x**2)',[('复合式与严格原域',2),('反函数与定义域',2),('非单射反例',2)])
wr(6,'不等式与可行整数','medium',6,r'解\(\frac{(x-1)(x-4)}{x-2}\ge0\)，并列出0≤x≤5内所有整数解。','[1,2)∪[4,∞)；整数1,4,5。',['临界点1、2、4；其中2不在定义域。','四段符号分别负、正、负、正；1和4可取。','与[0,5]交后整点为1,4,5；x=2不可取。'],'((x-1)*(x-4)/(x-2)).subs(x,5)','4/3',[('临界点与定义域',2),('符号和区间',2),('交集整数且不含分母零点',2)])
wr(10,'三角形面积与外接圆','medium',6,r'三角形ABC中AB=5、AC=7、∠A=60°。求BC、面积和外接圆半径，答案保留根号。','BC=√39；面积35√3/4；R=√13。',['余弦定律BC²=25+49−35=39。','面积=(1/2)·5·7·sin60°=35√3/4。','正弦定律R=BC/(2sin A)=√39/√3=√13。'],'sqrt(39)/(2*sin(pi/3))','sqrt(13)',[('余弦定律求边',2),('面积',2),('外接圆与根号化简',2)])
wr(11,'三角合成与区间解','medium',6,r'把\(\sin x+\sqrt3\cos x\)写成\(R\sin(x+\alpha)\)，R>0、0<α<π/2；并解该式在0≤x<2π内等于1的全部x。','R=2,α=π/3；x=π/2或11π/6。',['匹配Rcosα=1、Rsinα=√3，故R=2、α=π/3。','方程化为sin(x+π/3)=1/2，两支为π/6+2kπ或5π/6+2kπ。','减π/3并筛原区间得11π/6、π/2，逐一代回为1。'],'sin(pi/2)+sqrt(3)*cos(pi/2)','1',[('合成参数',2),('两支一般解',2),('区间筛选与回代',2)])
wr(16,'圆和切线的几何核对','medium',6,r'圆C过(0,0)、(4,0)、(0,6)。(a)求圆方程；(b)求圆在原点的切线；(c)判断点(2,3)的位置。','(x−2)²+(y−3)²=13；2x+3y=0；(2,3)为圆心。',['设x²+y²+Dx+Ey+F=0，原点给F=0，另外两点给D=−4,E=−6。','配方圆心(2,3)、半径√13；原点半径向量(−2,−3)，切线2x+3y=0。','(2,3)距圆心0，明确在圆内且为圆心。'],'(0-2)**2+(0-3)**2','13',[('三点定圆',2),('切线法向关系',2),('配方与位置检验',2)])
wr(22,'极值与闭区间端点','medium',6,r'\(f(x)=x^3-3x\)。(a)分类所有驻点；(b)求[-2,3]上的最大值和最小值，写出达到位置。','局部极大(−1,2)，局部极小(1,−2)；闭区间最大18于3，最小−2于−2及1。',['f′=3(x−1)(x+1)，负到正等符号分析：−1为极大，1为极小。','闭区间还须检端点f(−2)=−2、f(3)=18。','与f(−1)=2、f(1)=−2比较，最小在两处达到。'],'(x**3-3*x).subs(x,3)','18',[('驻点及增减判断',2),('端点与驻点值完整',2),('全局最值及所有达到点',2)])
wr(24,'区域与旋转轴','medium',6,r'区域R由\(y=x^2\)与\(y=2x\)围成。(a)求R面积；(b)求R绕x轴旋转一周的体积；解释上下函数选择。','面积4/3；体积64π/15。',['交点x²=2x给0与2；其间2x≥x²。','面积∫0²(2x−x²)dx=4/3。','垫片半径外2x、内x²，V=π∫0²(4x²−x⁴)dx=64π/15。'],'pi*integrate(4*x**2-x**4,(x,0,2))','64*pi/15',[('交点及上下曲线',2),('面积计算',2),('正确轴与平方半径体积',2)])
wr(26,'Bayes与独立重检','medium',6,r'某批零件次品率1/5。一次检验对次品报阳概率9/10，对正品报阳概率1/10。(a)求阳性率；(b)已知阳性求次品概率；(c)若在零件状态给定时两次检验独立，求两次均阳后的次品概率。','阳性13/50；一次9/13；两次81/85。',['全概率P(+)=1/5·9/10+4/5·1/10=13/50。','Bayes给(9/50)/(13/50)=9/13。','条件独立时P(次∩++)=81/500，正∩++=4/500，所以81/85；不是把无条件阳性率平方。'],'(Rational(1,5)*Rational(9,10)**2)/(Rational(1,5)*Rational(9,10)**2+Rational(4,5)*Rational(1,10)**2)','81/85',[('全概率',2),('一次条件概率',2),('说明条件独立并求双阳后验',2)])
wr(28,'变指数求导与切线','medium',6,r'在x>0上\(f(x)=x^x\)。(a)用对数微分求f′；(b)求x=1处切线；(c)证明f在x=e⁻¹达到最小值。','f′=x^x(ln x+1)；切线y=x；最小值exp(−1/e)。',['取ln f=x ln x，导出f′/f=ln x+1。','x=1时f=1,f′=1，故y−1=x−1。','因x^x>0，导数号随ln x+1，在e⁻¹左右负到正；代值为exp(−1/e)。'],'diff(x**x,x)','x**x*(log(x)+1)',[('正域与对数微分',2),('点及切线',2),('驻点变号及最小值',2)])
wr(29,'部分分式与原域','medium',6,r'求\(\int\frac{3x+1}{(x-1)(x+1)}dx\)，并说明结果在哪些区间适用。','2ln|x−1|+ln|x+1|+C；在(−∞,−1)、(−1,1)、(1,∞)分别适用，常数可不同。',['设A/(x−1)+B/(x+1)，解A+B=3,A−B=1，得A=2,B=1。','分别积分得到两个绝对值对数。','原函数只在不跨越极点的连通区间定义；求导回到原分式。'],'diff(2*log(x-1)+log(x+1),x)','(3*x+1)/((x-1)*(x+1))',[('完整部分分式',2),('积分及常数',2),('三个区间与验导',2)])
wr(30,'指数衰变与单位','medium',6,r'样品质量满足dm/dt=−km，k>0，t以小时计。m(0)=80克，6小时后剩40克。(a)求模型；(b)何时剩10克？','m(t)=80·2^(−t/6)；18小时。',['分离积分ln m=−kt+C，对质量正支有m=80e^(−kt)。','代6小时得e^(−6k)=1/2，k=ln2/6。','10/80=1/8=(1/2)³，所以t=18小时；回代为10。'],'80*2**(-sp.Rational(18,6))'.replace('sp.Rational','Rational'),'10',[('解微分方程并定初值',2),('由半衰期定k及单位',2),('求时刻并代回',2)])
wr(31,'归纳和有效域','medium',6,r'用数学归纳法证明对所有正整数n，\(\sum_{k=1}^n k(k+1)=n(n+1)(n+2)/3\)。','基步n=1成立；由k到k+1加(k+1)(k+2)得到目标。',['n=1左2右2，成立。','设n=k时和=k(k+1)(k+2)/3。','加下一项(k+1)(k+2)，提出公因子得(k+1)(k+2)(k+3)/3，完成归纳。'],'factor(x*(x+1)*(x+2)/3+(x+1)*(x+2))','(x+1)*(x+2)*(x+3)/3',[('明确基步',2),('归纳假设与加入正确项',2),('化成n=k+1并下结论',2)])
wr(33,'椭圆焦点与切线','medium',6,r'椭圆\(x^2/25+y^2/9=1\)。(a)求焦点；(b)求点(3,12/5)处切线；(c)验证该点到两焦点的距离和。','焦点(±4,0)；3x/25+4y/15=1；焦距和10。',['a=5,b=3,c=√(25−9)=4。','点满足9/25+(144/25)/9=1；切线xx0/25+yy0/9=1。','到(4,0)距离13/5，到(−4,0)距离37/5，相加10。'],'sqrt((3-4)**2+Rational(12,5)**2)+sqrt((3+4)**2+Rational(12,5)**2)','10',[('焦点参数',2),('点验证与切线',2),('两距离和',2)])
wr(34,'四根与复平面','medium',6,r'求方程z⁴=−16的全部根，写出极形式及代数形式，并说明根在复平面的位置关系。','z=2(cos(π/4+kπ/2)+i sin(π/4+kπ/2))，k=0,1,2,3；即±√2±i√2。',['右边模16、辐角π+2kπ。','四次根模2，角π/4+kπ/2，共4个互异根。','四点在模2圆上等间隔成正方形；每根四次方均为−16。'],'expand((sqrt(2)+I*sqrt(2))**4)','-16',[('模与全部辐角',2),('列四个互异根',2),('几何关系与回代',2)])
# Integrated 10-mark questions. These are deliberately not short questions with inflated marks.
wr(5,'绝对值函数与反函数限制','hard',10,r'\(f(x)=|x-1|+|x+2|\)。(a)写分段式；(b)解f(x)=7；(c)求全域最小值及全部达到点；(d)把f限制到[1,∞)，求反函数及其定义域。','分段−2x−1(x<−2)、3(−2≤x≤1)、2x+1(x>1)；解−4,3；最小3在[−2,1]；逆(x−1)/2，输入x≥3。',['以−2、1为分界逐项去绝对值，注意边界两式相合。','左支−2x−1=7得−4，右支2x+1=7得3，中支恒3不提供解。','全域f≥3，且整段[−2,1]都达到，不能只报一个驻点。','在[1,∞)函数2x+1严格递增，值域[3,∞)；反解得到(x−1)/2。','把反函数代回原限制支得到输入；不能为全实数f声称单射。'],'(2*((x-1)/2)+1)','x',[('完整分段及边界',3),('两解及区间验根',2),('最小值和完整达到集',2),('逆函数、域及回代',3)])
wr(22,'最值、参数和面积综合','hard',10,r'\(f_a(x)=x^3-3ax\)，a>0。(a)求两个驻点并分类；(b)若局部极大值与极小值之差为32，求a；(c)用所得a求曲线与x轴围成的总面积。','驻点±√a；a=4；f=x³−12x；总面积72。',['f′=3(x²−a)，三段符号为正、负、正，所以−√a为极大、√a为极小。','对应值分别2a^(3/2)、−2a^(3/2)，差4a^(3/2)=32，得a=4。','f=x(x²−12)，零点−2√3、0、2√3。','函数奇对称，两侧面积相等；在(0,2√3)函数为负，面积=2∫0^(2√3)(12x−x³)dx=72。','验算极大在−2为16、极小在2为−16，差32；总面积非有号积分0。'],'2*integrate(12*x-x**3,(x,0,2*sqrt(3)))','72',[('驻点及正确变号分类',3),('极值差求参数',2),('全部交点和两块区域',2),('分段面积及核对',3)])
wr(24,'两轴旋转与量纲比较','hard',10,r'区域R由\(y=x^2\)与\(y=4\)及y轴围成，取第一象限部分。(a)求面积；(b)求R绕x轴旋转体积；(c)改绕y轴旋转求体积；(d)比较并解释为何同区域不保证同体积。','面积16/3；Vx=128π/5；Vy=8π；两者不同。',['第一象限交点x=2，区域0≤x≤2，x²≤y≤4。','面积∫0²(4−x²)dx=16/3。','绕x轴外半径4、内半径x²：π∫0²(16−x⁴)dx=128π/5。','绕y轴用y：0≤y≤4，0≤x≤√y，圆盘体积π∫0⁴y dy=8π。','旋转轴改变点的转动半径分布，面积相同不代表这两种三维体积相同。'],'pi*integrate(16-x**4,(x,0,2))','128*pi/5',[('界限与面积',2),('x轴垫片及积分',3),('y轴圆盘及积分',3),('比较和半径解释',2)])
wr(26,'抽样条件与回收策略','hard',10,r'盒中3红2蓝，不放回依次抽两球。(a)求两球同色概率；(b)已知至少一红，求两红概率；(c)若改为每次抽后放回，重新求(b)；(d)解释(c)中改变了哪个独立性条件。','(a)2/5；(b)1/3；(c)3/7；放回使两次颜色独立。',['无放回同色=[C(3,2)+C(2,2)]/C(5,2)=4/10=2/5。','两红概率3/10；至少一红=1−两蓝=9/10，所以条件概率1/3。','放回两红9/25，至少一红1−4/25=21/25，所以3/7。','无放回时第二次红概率依首球颜色改变；放回时始终3/5，可乘独立概率。','两种模型的条件样本分母不同，不沿用旧9/10。'],'(Rational(3,5)**2)/(1-Rational(2,5)**2)','3/7',[('无放回同色',2),('条件分母和两红',3),('放回条件概率',3),('独立性解释',2)])
wr(28,'隐函数、切线与局部模型','hard',10,r'曲线\(x^2+xy+y^2=7\)。(a)证明在点(1,2)附近可将y视为x的可导函数并求y′；(b)求该点切线；(c)求该点二阶导数；(d)据切线估计x=1.02时同一局部分支的y，并判断相对于曲线是偏大还是偏小。','y′=−4/5；4x+5y=14；y″=−42/125；切线估计1.984，偏大。',['解出局部分支y=(−x+√(28−3x²))/2；在(1,2)取正根支，根号内在邻域为正，所以该分支可导。','一阶式2x+y+(x+2y)y′=0得−4/5，切线y−2=−4(x−1)/5。','再微分得2+2y′+2(y′)²+(x+2y)y″=0，代值得y″=−42/125。','dy≈(−4/5)·0.02=−0.016，所以y≈1.984。','二阶导数在此邻域连续且负，该分支凹向下，切线在上方，估计偏大；说明仅是局部小步长近似。'],'-(2+2*Rational(-4,5)+2*Rational(-4,5)**2)/5','-42/125',[('可导条件和一阶斜率',2),('切线',2),('完整二阶微分',3),('估计及有依据误差方向',3)])
wr(29,'换元、分部与极限校核','hard',10,r'定义\(F(a)=\int_1^a\ln x\,dx\)，a>0。(a)求F；(b)判断F的增减与最小值；(c)解F(a)=1；(d)求\(\lim_{a\to1}F(a)/(a-1)^2\)。','F=a ln a−a+1；(0,1)减、(1,∞)增，最小0；F=1解a=e；极限1/2。',['分部积分u=lnx，dv=dx，得F=a lna−a+1。','F′=ln a，故在1两侧负到正，最小F(1)=0。','F=1等价a(ln a−1)=0，因a>0，只有a=e。','极限为0/0；一次洛必达成ln a/[2(a−1)]，再一次为1/(2a)，极限1/2。','原域a>0排除a=0，即使a lna的极限存在也不能把0当方程解。'],'limit((x*log(x)-x+1)/(x-1)**2,x,1)','1/2',[('分部求F含定积分常数',3),('导数号与最小值',2),('域内解方程',2),('极限条件与两次计算',3)])
wr(31,'归纳、界与数值方法','hard',10,r'\(s_n=\sum_{k=1}^n\frac1{k(k+1)}\)。(a)用归纳法证明s_n=n/(n+1)；(b)求s_n>0.99的最小正整数n；(c)令f(x)=x/(x+1)−0.99，写Newton迭代式，并从x0=9求x1；(d)说明为何最小整数答案不能仅由一次迭代读出。','s_n=n/(n+1)；n=100；x1=18；一次近似不证严格整数不等式。',['n=1等式1/2成立；在k式加1/[(k+1)(k+2)]得(k+1)/(k+2)。','不等式1−1/(n+1)>.99给n+1>100，故n>99，最小100。','f′=1/(x+1)²；迭代x_{j+1}=x_j−[x_j/(x_j+1)−.99](x_j+1)²。','x0=9时f=−.09、f′=.01，x1=18。','连续方程的根是99；严格>要求整数100，一次迭代未给误差界且尚未到根。'],'9-(Rational(9,10)-Rational(99,100))*100','18',[('基步和完整归纳',3),('严格整数阈值',2),('导数迭代及x1',3),('方程近似与严格不等式的区别',2)])
wr(33,'抛物线最短距离与交点数','hard',10,r'抛物线\(y=x^2\)，点P=(0,2)。(a)求抛物线上点到P距离平方的表达式；(b)求最短距离及所有最近点；(c)以P为圆心的圆与抛物线相交于4个不同点，求半径r范围。','d²=x⁴−3x²+4；最短√7/2，最近点(±√(3/2),3/2)；√7/2<r<2。',['d²=x²+(x²−2)²=x⁴−3x²+4。','令u=x²≥0，则d²=(u−3/2)²+7/4，最小7/4在u=3/2取到。','最近点两支都保留，y=3/2。','交点方程u²−3u+4−r²=0要有两个互异正u，方能给4个不同x。','判别式4r²−7>0、根和3>0、根积4−r²>0，合并√7/2<r<2；端点分别切触或含x=0不能计4点。'],'(x**4-3*x**2+4).subs(x,sqrt(Rational(3,2)))','7/4',[('正确距离平方及u域',2),('配方最短与两个最近点',3),('两个正且异的u条件',3),('合并范围及端点解释',2)])
# Original integrated ten-mark items required for the verified four-group old format.
wr(10,'三角形边角与双圆半径','medium',10,r'三角形ABC中，a=7、b=9，且\(\cos C=1/3\)。(a)求边c；(b)求面积Δ；(c)求外接圆半径R；(d)求内切圆半径r。保留根式并说明采用的角度分支。','c=2√22；Δ=21√2；R=3√11/2；r=21√2/(8+√22)。',['三角形内角0<C<π，cos C=1/3>0使C为锐角，sin C=√(1−1/9)=2√2/3，不能取负根。','余弦定律c²=7²+9²−2·7·9/3=88，故c=2√22；2<c<16满足三角不等式。','Δ=ab sin C/2=21√2，用海伦公式可再次核算面积平方882。','扩展正弦定律2R=c/sin C，故R=3√11/2；这里c对应C而不能用a直接除sin C。','半周长s=(7+9+2√22)/2=8+√22；用Δ=rs得r=21√2/(8+√22)>0，且r<R，量纲均为长度。'],'(7**2+9**2-2*7*9/3-88)**2+(7*9*sqrt(1-Rational(1,9))/2-21*sqrt(2))**2+(2*sqrt(22)/(2*sqrt(Rational(8,9)))-3*sqrt(11)/2)**2','0',[('余弦定律求c并选正根',2),('内角分支与面积',3),('外接圆关系与R',2),('半周长、内切圆关系与核对',3)])
wr(11,'辅助角、一般根与周期积分','medium',10,r'令\(f(x)=3\sin x-4\cos x\)。(a)化为\(R\sin(x-\alpha)\)，规定R>0、0<α<π/2；(b)解f(x)=0在0≤x<2π的全部解；(c)计算\(\int_0^{2\pi} f(x)^2dx\)；(d)求f(x)+1的值域。','R=5，α=arctan(4/3)；零点α和α+π；积分25π；值域[−4,6]。',['展开R sin(x−α)=R cosα sinx−R sinα cosx，对比得R cosα=3、R sinα=4，故R=5、tanα=4/3，按指定范围唯一。','sin(x−α)=0给x=α+kπ；由于0<α<π/2，0≤x<2π仅k=0、1合要求，不把2π端点补进来。','平方展开为9sin²x+16cos²x−24sinx cosx；一个完整周期内前两项积分分别9π和16π，混合项为0。','也可用25sin²(x−α)的周期积分核算，结果25π；正负函数的平方积分不等于f的积分平方。','由sin范围[−1,1]，f范围[−5,5]，平移1得到[−4,6]，两端均能达到。'],'integrate((3*sin(x)-4*cos(x))**2,(x,0,2*pi))','25*pi',[('R、相位和分支',2),('完整根与区间筛选',3),('展开积分及核对',3),('值域及可达端点',2)])
wr(3,'因式、分式域与根的对称和','medium',10,r'\(p(x)=x^3-2x^2-5x+6\)。(a)证明x−1是因式并求商式；(b)求p的全部实根；(c)解\(p(x)/(x-1)\ge0\)，写明定义域；(d)求全部实根的平方和与倒数和。','商x²−x−6；根−2,1,3；解(−∞,−2]∪[3,∞)，原域x≠1；平方和14，倒数和5/6。',['p(1)=1−2−5+6=0，由因式定理可除x−1，长除或综合除得到x²−x−6。','商式分解为(x−3)(x+2)，所以p=(x−1)(x−3)(x+2)，三根互异，代回均为0。','原分式要求x≠1；约分只在此域内成立。比较(x−3)(x+2)≥0的符号，解x≤−2或x≥3，两端使分子0且分母不为0。','平方和=(−2)²+1²+3²=14；倒数和=−1/2+1+1/3=5/6。','用韦达核算：根和2、两两积−5、根积−6，平方和2²−2(−5)=14，倒数和(−5)/(−6)=5/6；没有零根才可求倒数。'],'expand((x-1)*(x-3)*(x+2))-(x**3-2*x**2-5*x+6)','0',[('因式验证与商',2),('全部根',2),('原分式域和不等式',3),('对称和与韦达核对',3)])
wr(34,'复数极式、平方根与三次根','medium',10,r'\(z=1+\sqrt3 i\)。(a)写出模与主辐角，主值区间(−π,π]；(b)求z³；(c)求z的两个平方根并验算；(d)求w³=z³的全部根，说明为何不能只写w=z。','|z|=2，Arg z=π/3；z³=−8；平方根±(√6/2+i√2/2)；w=1+√3i,−2,1−√3i。',['模√(1+3)=2，z在第一象限，主辐角π/3，故z=2(cosπ/3+i sinπ/3)。','棣美弗给z³=8(cosπ+i sinπ)=−8；代数展开中实部1−9=−8、虚部3√3−3√3=0。','设平方根u+iv，则u²−v²=1、2uv=√3，且u²+v²=2，得到u²=3/2、v²=1/2，同号；两根为±(√6/2+i√2/2)。','平方验算实部6/4−2/4=1，虚部2√12/4=√3，证明两根均成立。','w³=−8的模为2，辐角(π+2kπ)/3，k=0,1,2，得到三根1+√3i、−2、1−√3i；三次方映射不单射，不能从w³=z³约成w=z。'],'(expand((1+sqrt(3)*I)**3)+8)**2+(expand((sqrt(6)/2+I*sqrt(2)/2)**2)-(1+sqrt(3)*I))**2','0',[('模与主辐角',2),('三次幂',2),('两个平方根及验算',3),('三次根完整性及解释',3)])
wr(16,'圆、切线长度与弦距','medium',10,r'圆C：\(x^2+y^2-6x+4y-12=0\)。(a)求圆心O与半径；(b)验证P=(8,−2)在圆上并求P处切线；(c)判断Q=(9,6)与圆的位置并求Q所引切线段长；(d)求直线3x+4y−11=0截圆的弦长。','O=(3,−2)，半径5；切线x=8；Q在圆外，切线长5√3；弦长2√21。',['配方得(x−3)²+(y+2)²=25，O=(3,−2)、r=5；常数配方需在两边同步。','OP=(5,0)，模5所以P在圆上。切线垂直水平半径，方程x=8，不以斜率0误写y=−2。','OQ=√(6²+8²)=10>5，故Q在圆外；半径与切线段垂直，切线长√(10²−5²)=5√3，两条切线段长相等。','O到给定直线距离=|3·3+4(−2)−11|/√25=2<5，故确有两交点。半弦长√(25−4)=√21，所以全弦2√21。','两种长度都用直角三角形，但(c)从圆心距平方减半径平方，(d)从半径平方减弦距平方，不能交换。'],'(sqrt((9-3)**2+(6+2)**2-25)-5*sqrt(3))**2+(2*sqrt(25-(Abs(3*3+4*(-2)-11)/5)**2)-2*sqrt(21))**2','0',[('标准式与圆心半径',2),('点与切线',2),('圆外判断及切线段长',3),('弦距、全弦及核对',3)])

# Curriculum mapping uses real known sections only; otherwise no subsection is invented.
for q in bank:
 if q['kind']=='mcq':
  assert q['topic'] in D,q['topic']
  for option,reason in zip(q['options'][1:],D[q['topic']]):option['reason']=reason
 p=R/f'data/base-lessons/math{q["primary_chapter"]:02}.json'
 if p.exists():
  # Do not guess which subsection just because chapter data exists.
  q['subchapter_id']=None
 assert sum(p['marks']for p in q['marking_points'])==q['marks']
assert len({q['id']for q in bank})==len(bank)
version='2026.1-'+hashlib.sha256(json.dumps(bank,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()[:12]
(OUT/'original-bank.json').write_text(json.dumps(dict(version=version,items=bank),ensure_ascii=False,indent=2)+'\n')
(OUT/'original-bank.js').write_text('window.MATH_EXAM_BANK='+json.dumps(dict(version=version,items=bank),ensure_ascii=False,separators=(',',':'))+';\n')
(R/'reports/math-exams/ORIGINAL_VERIFICATION.json').write_text(json.dumps(dict(status='pass',questions=len(bank),checks=checks,limits='Named symbolic/enumeration checks plus author solution review; not official marking scheme or empirical difficulty calibration.'),ensure_ascii=False,indent=2)+'\n')
print('Built',len(bank),'original verified items;',sum(q['kind']=='mcq'for q in bank),'MCQ;',sum(q['kind']=='written'for q in bank),'written')
